    match n {
        Num::U(u) => {
            let _ = write!(out, "{}", u);
        }
        Num::I(i) => {
            let _ = write!(out, "{}", i);
        }
        Num::F(f) => out.push_str(&fmt_f64(*f)),
    }
}

pub fn write_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),

