$O run --cmd 'material {"name":"X","color":"#ff0000"}' ; echo "code $?";
$O run --cmd 'material {"name":"Brick"}' ; echo "code $?";
$O run --cmd 'material {}' ; echo "code $?";
$O run --cmd 'material {"name":"Glass"}' ; echo "code $?";
$O run --cmd 'material {"name":"Grass", "texture": {"kind": "image", "path": "/workspace/assets/test_library/grass.png"}}' --save g.bimcraft; echo "code $?";
python3 -c "
import json
d=json.load(open('g.bimcraft'))
print(list(d.keys()))
print(d['images'])
print(d['materials']['Grass'])
print([ (k,v) for k,v in d['library'].items() if v['kind'] in ('material','picture','image')][-3:])
"

