class BR:
    def __init__(s,d): s.d=d; s.pos=0
    def bit(s):
        b=(s.d[s.pos>>3]>>(s.pos&7))&1; s.pos+=1; return b
    def bits(s,n):
        v=0
        for i in range(n): v|=s.bit()<<i
        return v
def build(lengths):
    maxl=max(lengths)
    bl_count=[0]*(maxl+1)
    for l in lengths:
        if l: bl_count[l]+=1
    code=0; next_code=[0]*(maxl+2)
    for b in range(1,maxl+1):
        code=(code+bl_count[b-1])<<1
        next_code[b]=code
    codes={}
    for n,l in enumerate(lengths):
        if l:
            codes[(l,next_code[l])]=n; next_code[l]+=1
    return codes
def decode(br,codes):
    code=0;l=0
    while True:
        code=(code<<1)|br.bit(); l+=1
        if (l,code) in codes: return codes[(l,code)]
