                cl=[0]*19
                for i in range(hclen): cl[order[i]]=br.bits(3)
                clc=build(cl)
                lens=[]
                while len(lens)<hlit+hdist:
                    sym=decode(br,clc)
                    if sym<16: lens.append(sym)
                    elif sym==16: r_=br.bits(2)+3; lens+= [lens[-1]]*r_
                    elif sym==17: r_=br.bits(3)+3; lens+=[0]*r_
                    else: r_=br.bits(7)+11; lens+=[0]*r_
                lit=lens[:hlit]; dist=lens[hlit:]
            lc=build(lit); dc=build(dist)
            while True:
                s=decode(br,lc)
                if s<256: out.append(('L',s))
