cd /tmp/media-agent/w1 && python3 -c "
import json
d=json.load(open('y.bimcraft'))
lib=d['library']
g2n={v['guid']:(v['kind'],v['name']) for v in lib.values()}
fams=d['families']
for fn,f in fams.items():
    mats=[]
    for i,fo in enumerate(f.get('forms',[])):
        if 'material' in fo: mats.append(('form',i,g2n.get(fo['material'],fo['material'])))
    for p in f.get('parameters',[]):
        if p.get('kind')=='material': mats.append(('param',p['name'],p.get('value'), g2n.get(p.get('value'))))
    for tn,t in f.get('types',{}).items():
        for k,v in t.items():
            if isinstance(v,str) and v in g2n: mats.append(('type',tn,k,g2n[v]))
    print(fn, mats[:8])
" | head -50

