        if self.n < k {
            self.fill();
            if self.n < k {
                return Err(Stop::Short);
            }
        }
        let v = (self.buf & ((1u64 << k) - 1)) as u32;
        self.buf >>= k;
        self.n -= k;
        self.used += k as usize;
        Ok(v)
    }
    #[inline]
    fn peek(&mut self, k: u32) -> (u32, u32) {
        if self.n < k {
            self.fill();
        }
        let have = self.n.min(k);
        ((self.buf & ((1u64 << k) - 1)) as u32, have)
    }
    #[inline]
    fn drop_bits(&mut self, k: u32) {
        self.buf >>= k;
        self.n -= k;
        self.used += k as usize;
    }
