    fast: Vec<u16>,
}

enum Build {
    Ok(Huff),
    /// No symbol has a code.
    Empty,
    Bad,
}

/// Builds a code from code lengths as zlib accepts one: complete, or a single code of length 1.
fn build(lengths: &[u8]) -> Build {
    let mut count = [0u16; 16];
    for &l in lengths {
        count[l as usize] += 1;
    }
    count[0] = 0;
    let used: u32 = count[1..].iter().map(|&c| c as u32).sum();
    if used == 0 {
        return Build::Empty;
    }
    let mut left: i32 = 1;
    for len in 1..16 {
        left <<= 1;
        left -= count[len] as i32;
        if left < 0 {
            return Build::Bad;
        }
    }
    if left > 0 && !(used == 1 && count[1] == 1) {
        return Build::Bad;
    }
    let mut offs = [0u16; 16];
    for len in 1..15 {
        offs[len + 1] = offs[len] + count[len];
    }
    let mut symbols = vec![0u16; used as usize];
    for (s, &l) in lengths.iter().enumerate() {
        if l != 0 {
            symbols[offs[l as usize] as usize] = s as u16;
            offs[l as usize] += 1;
        }
    }
    // the fast table: canonical codes, bit-reversed
    let mut fast = vec![0u16; 1 << FAST];
    let mut code: u32 = 0;
    let mut idx = 0usize;
    for len in 1..16u32 {
        for _ in 0..count[len as usize] {
            if len <= FAST {
                let rev = code.reverse_bits() >> (32 - len);
                let sym = symbols[idx] as u32;
                let mut f = rev;
                while f < (1 << FAST) {
                    fast[f as usize] = (sym << 4 | len) as u16;
                    f += 1 << len;
                }
            }
            code += 1;
            idx += 1;
        }
        code <<= 1;
    }
    Build::Ok(Huff { count, symbols, fast })
}

/// Decodes one symbol; None for a code the (incomplete) tree has no symbol for.
#[inline]
fn decode_sym(b: &mut Bits, h: &Huff) -> Result<Option<u16>, Stop> {
    let (v, have) = b.peek(FAST);
    let e = h.fast[(v & ((1 << FAST) - 1)) as usize];
    if e != 0 {
        let len = (e & 15) as u32;
        if len <= have {
            b.drop_bits(len);
            return Ok(Some(e >> 4));
        }
    }
    // the slow way, a bit at a time
    let mut code: i32 = 0;
    let mut first: i32 = 0;
    let mut index: i32 = 0;
    let save = (b.buf, b.n, b.next, b.used);
    for len in 1..16 {
        let bit = match b.bits(1) {
            Ok(x) => x,
            Err(s) => {
                (b.buf, b.n, b.next, b.used) = save;
                return Err(s);
            }
        };
        code |= bit as i32;
        let count = h.count[len] as i32;
        if code - count < first {
            return Ok(Some(h.symbols[(index + (code - first)) as usize]));
        }
        index += count;
        first += count;
        first <<= 1;
        code <<= 1;
    }
    Ok(None)
}

