    ok = not diffs
    name = label or ' '.join(args)[:200]
    if ok:
        if not quiet: print('SAME', name)
    else:
        print('DIFF', name)
        for l in diffs: print('   ', l)
    return ok

def cmds(*cs, save=True):
    a = ['run']
    for c in cs:
        a += ['--cmd', c]
    if save:
        a += ['--save', 'x.bimcraft']
    return a

