import zlib, struct

SIG = b'\x89PNG\r\n\x1a\n'

def chunk(typ, data, crc=None):
    if isinstance(typ, str):
        typ = typ.encode('latin-1')
    c = zlib.crc32(typ + data) & 0xffffffff if crc is None else crc
    return struct.pack('>I', len(data)) + typ + data + struct.pack('>I', c)

def ihdr(w, h, depth=8, ctype=2, comp=0, filt=0, inter=0):
    return chunk('IHDR', struct.pack('>IIBBBBB', w, h, depth, ctype, comp, filt, inter))

CHANNELS = {0: 1, 2: 3, 3: 1, 4: 2, 6: 4}

def pack_row(samples, depth):
    """samples: list of ints (all channels flattened) -> bytes"""
    if depth == 8:
        return bytes(samples)
    if depth == 16:
        out = b''
        for s in samples:
            out += struct.pack('>H', s)
        return out
    # sub-byte
    out = bytearray()
    per = 8 // depth
    for i in range(0, len(samples), per):
        b = 0
        grp = samples[i:i + per]
        for k in range(per):
            v = grp[k] if k < len(grp) else 0
            b |= (v & ((1 << depth) - 1)) << (8 - depth * (k + 1))
        out.append(b)
    return bytes(out)

def raw_image(rows, depth, filt=0):
    """rows: list of list of samples; returns filtered bytes with filter type per row (0 only or given)"""
    out = b''
    for r in rows:
        out += bytes([filt if isinstance(filt, int) else 0]) + pack_row(r, depth)
    return out

def adam7_passes(w, h):
    passes = [(0, 0, 8, 8), (4, 0, 8, 8), (0, 4, 4, 8), (2, 0, 4, 4), (0, 2, 2, 4), (1, 0, 2, 2), (0, 1, 1, 2)]
    res = []
    for (x0, y0, dx, dy) in passes:
        xs = list(range(x0, w, dx))
        ys = list(range(y0, h, dy))
        res.append((xs, ys))
    return res

def make_png(w, h, pixels, depth=8, ctype=2, interlace=0, extra_before=(), extra_after=(), level=6, plte=None, trns=None, idat_split=None, filt=0, raw_override=None):
    """pixels: list of rows, each a list of per-pixel tuples (channels)"""
    ch = CHANNELS[ctype]
    def flat(row):
        o = []
        for px in row:
            if isinstance(px, int):
                o.append(px)
            else:
                o.extend(px)
        return o
    if raw_override is not None:
        raw = raw_override
    elif interlace:
        raw = b''
        for xs, ys in adam7_passes(w, h):
            if not xs or not ys:
                continue
            for y in ys:
                row = [pixels[y][x] for x in xs]
                raw += bytes([0]) + pack_row(flat(row), depth)
    else:
        raw = b''.join(bytes([0]) + pack_row(flat(r), depth) for r in pixels)
    data = zlib.compress(raw, level)
    out = SIG + ihdr(w, h, depth, ctype, 0, 0, interlace)
    for c in extra_before:
        out += c
    if plte is not None:
        out += chunk('PLTE', bytes(b for c in plte for b in c))
    if trns is not None:
        out += chunk('tRNS', trns)
    if idat_split:
        for i in range(0, len(data), idat_split):
            out += chunk('IDAT', data[i:i + idat_split])
    else:
        out += chunk('IDAT', data)
    for c in extra_after:
        out += c
    out += chunk('IEND', b'')
    return out

def parse_png(data):
    """returns list of (type, data)"""
    assert data[:8] == SIG
    i = 8
    res = []
    while i < len(data):
        n = struct.unpack('>I', data[i:i + 4])[0]
        t = data[i + 4:i + 8]
        d = data[i + 8:i + 8 + n]
        res.append((t.decode('latin-1'), d))
        i += 12 + n
    return res

def decode_stored(png):
    """decode an RGBA8 non-interlaced filter-0 PNG -> (w,h,rows of RGBA tuples)"""
    ch = parse_png(png)
    w, h = struct.unpack('>II', ch[0][1][:8])
    idat = b''.join(d for t, d in ch if t == 'IDAT')
    raw = zlib.decompress(idat)
    hdr = ch[0][1]
    ctype = hdr[9]
    nch = CHANNELS[ctype]
    stride = w * nch
    rows = []
    for y in range(h):
        f = raw[y * (stride + 1)]
        r = raw[y * (stride + 1) + 1:(y + 1) * (stride + 1)]
        assert f == 0, f
        rows.append([tuple(r[x * nch:(x + 1) * nch]) for x in range(w)])
    return w, h, rows

