Comp.hdr_last = HEADER[53] & 31 if len(HEADER) > 53 else None

def stored_size(raw):
    M = 65535
    return (max(raw - 1, 0) // M) * (M + 5) + (raw % M + 5) + 6

def stored(rows_raw):
    data = b''.join(rows_raw)
    out = bytearray(b'\x78\x01')
    blocks = []
    i = 0
    if len(data) == 0:
        blocks = [b'']
    while i < len(data):
        blocks.append(data[i:i + 65535]); i += 65535
    for k, b in enumerate(blocks):
        last = 1 if k == len(blocks) - 1 else 0
        n = len(b)
        out += bytes([last, n & 255, n >> 8, (~n) & 255, ((~n) >> 8) & 255]) + b
    out += struct.pack('>I', zlib.adler32(data) & 0xffffffff)
    return bytes(out)

def encode_rgba(w, h, rows, split_filter_byte=True):
    """rows: list of bytes (RGBA)"""
    c = Comp()
    prev = None
    for r in rows:
        f = bytearray(len(r))
        for i in range(len(r)):
            f[i] = (r[i] - (r[i - 4] if i >= 4 else 0)) & 255
        if split_filter_byte:
            c.write_data(b'\x01')
            c.write_data(bytes(f))
        else:
            c.write_data(b'\x01' + bytes(f))
    comp = c.finish()
    if len(comp) > stored_size((w * 4 + 1) * h):
        comp = stored([b'\x00' + bytes(r) for r in rows])
    return comp

