"""Run favorites scenarios on the original (or mine) with an isolated config dir."""
import os, sys, json, subprocess, tempfile, shutil
sys.path.insert(0, '/tmp/media-agent')
from o import ORIG, MINE

def runf(cmds, exe=ORIG, env_mode='xdg', save=False, pre_files=None, keep=False):
    d = tempfile.mkdtemp(prefix='fav')
    home = os.path.join(d, 'home'); os.makedirs(home)
    xdg = os.path.join(d, 'xdg'); os.makedirs(xdg)
    work = os.path.join(d, 'work'); os.makedirs(work)
    env = {'PATH': os.environ['PATH'], 'HOME': home}
    if env_mode == 'xdg':
        env['XDG_CONFIG_HOME'] = xdg
    elif env_mode == 'fav':
        env['BIMCRAFT_FAVORITES'] = os.path.join(d, 'favs', 'my.json')
    elif env_mode == 'favdir':
        env['BIMCRAFT_FAVORITES'] = os.path.join(d, 'favs')
    if pre_files:
        for rel, content in pre_files.items():
            p = os.path.join(d, rel)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            open(p, 'wb').write(content if isinstance(content, bytes) else content.encode())
    args = [exe, 'run']
    for c in cmds:
        args += ['--cmd', c.replace('@D', d)]
    if save:
        args += ['--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=work, capture_output=True, env=env, timeout=120)
    files = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            if rel.startswith('work/x.bimcraft'):
                continue
            files[rel] = open(full, 'rb').read()
    proj = None
    if save and os.path.exists(os.path.join(work, 'x.bimcraft')):
        proj = json.load(open(os.path.join(work, 'x.bimcraft')))
    out = p.stdout.decode().replace(d, '@D')
    err = p.stderr.decode().replace(d, '@D')
    if not keep:
        shutil.rmtree(d)
    return p.returncode, out, err, files, proj

if __name__ == '__main__':
    a = sys.argv[1:]
    exe = ORIG; mode = 'xdg'
    while a and a[0].startswith('-'):
        if a[0] == '-m': exe = MINE; a = a[1:]
        elif a[0] == '-e': mode = a[1]; a = a[2:]
        else: break
    code, out, err, files, _ = runf(a, exe, mode)
    print(out, err, 'code', code)
    for k, v in files.items():
        print('FILE', k, len(v))
        print(v.decode('utf-8', 'replace')[:3000])

