//! `paint`: a material laid over faces of elements, as Revit's Paint does. An element keeps it
//! in `params.Paint`, `{face: the material's GUID}`.

use crate::commands::params::*;
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

/// The faces an element of a category has to paint.
pub fn faces(cat: &str) -> Option<&'static [&'static str]> {
    match cat {
        "wall" => Some(&["exterior", "interior"]),
        "floor" | "roof" | "ceiling" => Some(&["top", "bottom"]),
        "column" | "component" | "door" | "window" | "stair" | "ramp" | "railing" => Some(&["all"]),
        _ => None,
    }
}

fn not_an_id(v: &Value) -> String {
    format!("paint: {} is not an element id or GUID", v.to_compact())
}

/// An element by its id (a number, or one in a string) or its GUID.
fn element(pr: &Project, v: &Value) -> Result<u64, String> {
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(|| not_an_id(v))?;
            if pr.elements.contains_key(&id) {
                Ok(id)
            } else {
                Err(format!("paint: no element {}", id))
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if let Ok(id) = t.parse::<u64>() {
                return if pr.elements.contains_key(&id) { Ok(id) } else { Err(format!("paint: no element {}", id)) };
            }
            match crate::model::normalize_guid(t) {
                Some(g) => pr.find_guid(&g).ok_or_else(|| format!("paint: no element {}", t)),
                None => Err(not_an_id(v)),
            }
        }
        _ => Err(not_an_id(v)),
    }
}

/// A material of the library by its name (or its GUID): its GUID.
pub fn material_ref(pr: &Project, name: &str) -> Option<String> {
    if super::material::material(pr, name).is_some() {
        return super::material::material_guid(pr, name);
    }
    let g = crate::model::normalize_guid(name)?;
    let n = super::material::material_name(pr, &g)?;
    super::material::material(pr, &n)?;
    Some(g)
}

pub fn cmd(s: &mut Session, p: &Value) -> Result<Value, String> {
    let refs: Vec<Value> = match p.get("ids") {
        Some(Value::Arr(a)) => a.clone(),
        Some(Value::Null) | None => match p.get("id") {
            Some(v) => vec![v.clone()],
            None => return Err("paint: `ids` [id, …] is required".into()),
        },
        Some(_) => return Err("paint: `ids` [id, …] is required".into()),
    };
    let pr = &mut s.project;
    let mut ids: Vec<u64> = Vec::new();
    for r in &refs {
        let id = element(pr, r)?;
        if !ids.contains(&id) {
            ids.push(id);
        }
    }
    let material = match p.get("material") {
        None => return Err("paint: `material` is required: a material's name, or null to take the paint off".into()),
        Some(Value::Null) => None,
        Some(Value::Str(s)) => {
            let n = s.trim();
            match material_ref(pr, n) {
                Some(g) => Some(g),
                None => return Err(format!("paint: the library has no `{}`; add it with `material`", n)),
            }
        }
        Some(v) => return Err(format!("paint: `material` is a material's name, or null, not {}", v.to_compact())),
    };
    let face = opt_text(p, "paint", "face")?;
    // every element first, then the paint
    let mut plan: Vec<(u64, Vec<&'static str>)> = Vec::new();
    for &id in &ids {
        let cat = pr.category(id).unwrap_or("").to_string();
        let fs = match faces(&cat) {
            Some(f) => f,
            None => return Err(format!("paint: {} {} has no face to paint", cat, id)),
        };
        let chosen: Vec<&'static str> = match &face {
            None => fs.to_vec(),
            Some(f) => match fs.iter().find(|x| **x == f.as_str()) {
                Some(x) => vec![*x],
                None => {
                    return Err(format!("paint: a {} has no face `{}`; its faces are {}", cat, f, fs.join(", ")));
                }
            },
        };
        plan.push((id, chosen));
    }
    for (id, chosen) in plan {
        let e = pr.el_mut(id).unwrap();
        let mut params = e.get("params").cloned().unwrap_or_else(Value::obj);
        let mut paint = params.get("Paint").cloned().unwrap_or_else(Value::obj);
        for f in chosen {
            let pm = paint.as_obj_mut().unwrap();
            match &material {
                Some(g) => pm.insert_sorted(f, Value::s(g)),
                None => {
                    pm.remove(f);
                }
            }
        }
        if paint.as_obj().map(|m| m.is_empty()).unwrap_or(true) {
            params.remove("Paint");
        } else if let Some(pm) = params.as_obj_mut() {
            pm.insert_sorted("Paint", paint);
        }
        if params.as_obj().map(|m| m.is_empty()).unwrap_or(true) {
            e.remove("params");
        } else {
            e.set("params", params);
        }
    }
    Ok(jobj! {"painted" => ids})
}

//! Reading a favorites file as serde reads it into the original's structs: the same errors
//! (`invalid type`, `missing field`, `unknown field`…) at the same line and column. The text is
//! known to be well-formed JSON here (its syntax errors come from `json::parse`).

use crate::json::Value;

pub struct De<'a> {
    s: &'a [u8],
    i: usize,
}

type R<T> = Result<T, String>;

/// A field of a struct: its name, and whether it may be left out.
struct Field {
    name: &'static str,
    required: bool,
}

const fn f(name: &'static str, required: bool) -> Field {
    Field { name, required }
}

impl<'a> De<'a> {
    pub fn new(s: &'a [u8]) -> De<'a> {
        De { s, i: 0 }
    }

    fn at(&self, i: usize) -> String {
        let i = i.min(self.s.len());
        let start = self.s[..i].iter().rposition(|&c| c == b'\n').map(|p| p + 1).unwrap_or(0);
        let line = 1 + self.s[..start].iter().filter(|&&c| c == b'\n').count();
        format!("line {} column {}", line, i - start)
    }
    fn err(&self, msg: &str) -> String {
        format!("{} at {}", msg, self.at(self.i))
    }
    fn peek_err(&self, msg: &str) -> String {
        format!("{} at {}", msg, self.at(self.i + 1))
    }
    fn ws(&mut self) -> Option<u8> {
        while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
        self.s.get(self.i).copied()
    }
    fn eat(&mut self, c: u8) {
        if self.ws() == Some(c) {
            self.i += 1;
        }
    }

    /// The end of a string whose opening quote is at `self.i`.
    fn string(&mut self) -> String {
        let start = self.i;
        self.i += 1;
        while self.i < self.s.len() {
            match self.s[self.i] {
                b'\\' => self.i += 2,
                b'"' => {
                    self.i += 1;
                    break;
                }
                _ => self.i += 1,
            }
        }
        match crate::json::parse_bytes(&self.s[start..self.i]) {
            Ok(Value::Str(s)) => s,
            _ => String::new(),
        }
    }
    /// A scalar or a whole value, parsed (the text being well-formed).
    fn scalar(&mut self) -> Value {
        let rest = std::str::from_utf8(&self.s[self.i..]).unwrap_or("");
        match crate::json::parse_prefix(rest) {
            Ok((v, n)) => {
                self.i += n;
                v
            }
            Err(_) => {
                self.i = self.s.len();
                Value::Null
            }
        }
    }
    fn skip(&mut self) {
        self.ws();
        self.scalar();
    }

    /// serde_json's "invalid type" for the value ahead: scalars are read first, `[` and `{` not.
    fn invalid_type(&mut self, exp: &str) -> String {
        match self.ws() {
            Some(b'[') => self.err(&format!("invalid type: sequence, expected {}", exp)),
            Some(b'{') => self.err(&format!("invalid type: map, expected {}", exp)),
            Some(b'"') => {
                let s = self.string();
                self.err(&format!("invalid type: string {:?}, expected {}", s, exp))
            }
            _ => {
                let v = self.scalar();
                let what = match &v {
                    Value::Null => "null".to_string(),
                    Value::Bool(b) => format!("boolean `{}`", b),
                    other => other.kind_name(),
                };
                self.err(&format!("invalid type: {}, expected {}", what, exp))
            }
        }
    }

    fn u_int(&mut self, max: u64, exp: &str) -> R<u64> {
        match self.ws() {
            Some(c) if c == b'-' || c.is_ascii_digit() => {
                let v = self.scalar();
                match v {
                    Value::Num(crate::json::Num::U(u)) if u <= max => Ok(u),
                    Value::Num(crate::json::Num::U(u)) => Err(self.err(&format!("invalid value: integer `{}`, expected {}", u, exp))),
                    Value::Num(crate::json::Num::I(i)) => Err(self.err(&format!("invalid value: integer `{}`, expected {}", i, exp))),
                    other => Err(self.err(&format!("invalid type: {}, expected {}", other.kind_name(), exp))),
                }
            }
            _ => Err(self.invalid_type(exp)),
        }
    }

    fn f64(&mut self) -> R<f64> {
        match self.ws() {
            Some(c) if c == b'-' || c.is_ascii_digit() => {
                let v = self.scalar();
                Ok(v.as_f64().unwrap_or(0.0))
            }
            _ => Err(self.invalid_type("f64")),
        }
    }

    fn string_value(&mut self) -> R<String> {
        match self.ws() {
            Some(b'"') => Ok(self.string()),
            _ => Err(self.invalid_type("a string")),
        }
    }

    fn opt<T>(&mut self, inner: impl FnOnce(&mut Self) -> R<T>) -> R<Option<T>> {
        if self.ws() == Some(b'n') {
            self.scalar();
            return Ok(None);
        }
        inner(self).map(Some)
    }

    /// A unit-variant enum, as a string of one of `variants`.
    fn variant(&mut self, variants: &[&str]) -> R<String> {
        match self.ws() {
            Some(b'"') => {
                let s = self.string();
                if variants.contains(&s.as_str()) {
                    Ok(s)
                } else {
                    let list: Vec<String> = variants.iter().map(|v| format!("`{}`", v)).collect();
                    Err(self.err(&format!("unknown variant `{}`, expected one of {}", s, list.join(", "))))
                }
            }
            _ => Err(self.peek_err("expected value")),
        }
    }

    /// `[T; n]`.
    fn array<T>(&mut self, n: usize, mut elem: impl FnMut(&mut Self) -> R<T>) -> R<Vec<T>> {
        let exp = format!("an array of length {}", n);
        if self.ws() != Some(b'[') {
            return Err(self.invalid_type(&exp));
        }
        self.i += 1;
        let mut out = Vec::new();
        for k in 0..n {
            if self.ws() == Some(b']') {
                self.i += 1;
                return Err(self.err(&format!("invalid length {}, expected {}", k, exp)));
            }
            if k > 0 {
                self.eat(b',');
            }
            out.push(elem(self)?);
        }
        match self.ws() {
            Some(b']') => {
                self.i += 1;
                Ok(out)
            }
            _ => {
                self.eat(b',');
                self.ws();
                Err(self.peek_err("trailing characters"))
            }
        }
    }

    /// A map of strings to values.
    fn map<T>(&mut self, mut val: impl FnMut(&mut Self, &str) -> R<T>) -> R<Vec<(String, T)>> {
        if self.ws() != Some(b'{') {
            return Err(self.invalid_type("a map"));
        }
        self.i += 1;
        let mut out: Vec<(String, T)> = Vec::new();
        let mut first = true;
        loop {
            if self.ws() == Some(b'}') {
                self.i += 1;
                return Ok(out);
            }
            if !first {
                self.eat(b',');
            }
            first = false;
            self.ws();
            let k = self.string();
            self.eat(b':');
            let v = val(self, &k)?;
            if let Some(slot) = out.iter_mut().find(|(kk, _)| *kk == k) {
                slot.1 = v;
            } else {
                out.push((k, v));
            }
        }
    }

    /// A struct with these fields (unknown ones refused): `val` reads the value of field `i`.
    fn strukt(&mut self, name: &str, fields: &[Field], mut val: impl FnMut(&mut Self, usize) -> R<()>) -> R<()> {
        let exp = format!("struct {}", name);
        match self.ws() {
            Some(b'{') => {}
            Some(b'[') => {
                // a struct may come as a sequence of its fields
                self.i += 1;
                let mut k = 0;
                loop {
                    if self.ws() == Some(b']') {
                        self.i += 1;
                        break;
                    }
                    if k > 0 {
                        self.eat(b',');
                    }
                    if k >= fields.len() {
                        self.ws();
                        return Err(self.peek_err("trailing characters"));
                    }
                    val(self, k)?;
                    k += 1;
                }
                if let Some(missing) = fields.iter().skip(k).find(|f| f.required) {
                    let _ = missing;
                    return Err(self.err(&format!("invalid length {}, expected {}", k, exp)));
                }
                return Ok(());
            }
            _ => return Err(self.invalid_type(&exp)),
        }
        self.i += 1;
        let mut seen = vec![false; fields.len()];
        let mut first = true;
        loop {
            if self.ws() == Some(b'}') {
                self.i += 1;
                break;
            }
            if !first {
                self.eat(b',');
            }
            first = false;
            self.ws();
            let k = self.string();
            match fields.iter().position(|f| f.name == k) {
                Some(fi) => {
                    if seen[fi] {
                        return Err(self.err(&format!("duplicate field `{}`", k)));
                    }
                    seen[fi] = true;
                    self.eat(b':');
                    val(self, fi)?;
                }
                None => {
                    let names: Vec<String> = fields.iter().map(|f| format!("`{}`", f.name)).collect();
                    let expected = match names.len() {
                        1 => format!("expected {}", names[0]),
                        2 => format!("expected {} or {}", names[0], names[1]),
                        _ => format!("expected one of {}", names.join(", ")),
                    };
                    return Err(self.err(&format!("unknown field `{}`, {}", k, expected)));
                }
            }
        }
        for (fi, fd) in fields.iter().enumerate() {
            if fd.required && !seen[fi] {
                return Err(self.err(&format!("missing field `{}`", fd.name)));
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- the favorites file

/// A picture kept with a favorite.
#[derive(Clone)]
pub struct PictureFile {
    pub name: String,
    pub png: String,
}

/// A favorite material: the material as the favorites file has it (patterns and its picture by
/// name), and the pictures it needs.
#[derive(Clone)]
pub struct MaterialEntry {
    /// The material, in file order (its texture's `image` a picture's id).
    pub material: Value,
    pub images: Vec<(String, PictureFile)>,
}

#[derive(Clone)]
pub struct FamilyEntry {
    pub family: Value,
    pub materials: Vec<(String, MaterialEntry)>,
}

#[derive(Default)]
pub struct Favorites {
    pub materials: Vec<(String, MaterialEntry)>,
    pub families: Vec<(String, FamilyEntry)>,
}

const PATTERNS: [&str; 10] = super::material::PATTERNS;
const KINDS: [&str; 11] = super::material::KINDS;

fn pair(de: &mut De) -> R<Value> {
    let a = de.array(2, |d| d.f64())?;
    Ok(Value::Arr(vec![Value::f(a[0]), Value::f(a[1])]))
}

fn texture(de: &mut De) -> R<Value> {
    let fields = [f("kind", true), f("size", true), f("angle", false), f("offset", false), f("image", false)];
    let mut kind = String::new();
    let mut size = Value::Null;
    let mut angle = 0.0;
    let mut offset = Value::Null;
    let mut image: Option<String> = None;
    de.strukt("Texture", &fields, |d, i| {
        match i {
            0 => kind = d.variant(&KINDS)?,
            1 => size = pair(d)?,
            2 => angle = d.f64()?,
            3 => offset = pair(d)?,
            _ => image = d.opt(|d| d.string_value())?,
        }
        Ok(())
    })?;
    let mut m = crate::json::Map::new();
    m.insert("kind", Value::Str(kind));
    m.insert("size", size);
    if angle != 0.0 {
        m.insert("angle", Value::f(angle));
    }
    if let Some(a) = offset.as_arr() {
        if a.iter().any(|x| x.as_f64() != Some(0.0)) {
            m.insert("offset", offset.clone());
        }
    }
    if let Some(g) = image {
        m.insert("image", Value::Str(g));
    }
    Ok(Value::Obj(m))
}

fn material(de: &mut De) -> R<Value> {
    let fields = [
        f("color", true),
        f("cut", false),
        f("surface", false),
        f("cut_pattern", false),
        f("surface_pattern", false),
        f("texture", false),
        f("transparency", false),
    ];
    let mut color = Value::Null;
    let mut cut = "none".to_string();
    let mut surface = "none".to_string();
    let mut cut_pattern = None;
    let mut surface_pattern = None;
    let mut tex = None;
    let mut transparency = 0u64;
    de.strukt("Material", &fields, |d, i| {
        match i {
            0 => {
                let c = d.array(3, |d| d.u_int(255, "u8"))?;
                color = Value::Arr(c.into_iter().map(Value::u).collect());
            }
            1 => cut = d.variant(&PATTERNS)?,
            2 => surface = d.variant(&PATTERNS)?,
            3 => cut_pattern = d.opt(|d| d.string_value())?,
            4 => surface_pattern = d.opt(|d| d.string_value())?,
            5 => tex = d.opt(texture)?,
            _ => transparency = d.u_int(255, "u8")?,
        }
        Ok(())
    })?;
    let mut m = crate::json::Map::new();
    m.insert("color", color);
    m.insert("cut", Value::Str(cut));
    m.insert("surface", Value::Str(surface));
    if let Some(p) = cut_pattern {
        m.insert("cut_pattern", Value::Str(p));
    }
    if let Some(p) = surface_pattern {
        m.insert("surface_pattern", Value::Str(p));
    }
    if let Some(t) = tex {
        m.insert("texture", t);
    }
    if transparency != 0 {
        m.insert("transparency", Value::u(transparency));
    }
    Ok(Value::Obj(m))
}

fn picture_file(de: &mut De) -> R<PictureFile> {
    let fields = [f("name", true), f("png", true)];
    let mut name = String::new();
    let mut png = String::new();
    de.strukt("PictureFile", &fields, |d, i| {
        if i == 0 {
            name = d.string_value()?;
        } else {
            png = d.string_value()?;
        }
        Ok(())
    })?;
    Ok(PictureFile { name, png })
}

fn material_entry(de: &mut De) -> R<MaterialEntry> {
    let fields = [f("material", true), f("images", false)];
    let mut mat = Value::Null;
    let mut images = Vec::new();
    de.strukt("MaterialEntry", &fields, |d, i| {
        if i == 0 {
            mat = material(d)?;
        } else {
            let mut v = d.map(|d, _| picture_file(d))?;
            v.sort_by(|a, b| a.0.cmp(&b.0));
            images = v;
        }
        Ok(())
    })?;
    Ok(MaterialEntry { material: mat, images })
}

fn family_entry(de: &mut De) -> R<FamilyEntry> {
    let fields = [f("family", true), f("materials", false)];
    let mut fam = Value::Null;
    let mut mats = Vec::new();
    de.strukt("FamilyEntry", &fields, |d, i| {
        if i == 0 {
            if d.ws() != Some(b'{') {
                return Err(d.invalid_type("struct Family"));
            }
            fam = d.scalar();
        } else {
            let mut v = d.map(|d, _| material_entry(d))?;
            v.sort_by(|a, b| a.0.cmp(&b.0));
            mats = v;
        }
        Ok(())
    })?;
    Ok(FamilyEntry { family: fam, materials: mats })
}

/// Reads a favorites file's text (already known to be JSON).
pub fn favorites(text: &[u8]) -> R<Favorites> {
    let mut de = De::new(text);
    let fields = [f("version", false), f("materials", false), f("families", false)];
    let mut out = Favorites::default();
    de.strukt("Favorites", &fields, |d, i| {
        match i {
            0 => {
                d.u_int(u32::MAX as u64, "u32")?;
            }
            1 => {
                let mut v = d.map(|d, _| material_entry(d))?;
                v.sort_by(|a, b| a.0.cmp(&b.0));
                out.materials = v;
            }
            _ => {
                let mut v = d.map(|d, _| family_entry(d))?;
                v.sort_by(|a, b| a.0.cmp(&b.0));
                out.families = v;
            }
        }
        Ok(())
    })?;
    if de.ws().is_some() {
        return Err(de.peek_err("trailing characters"));
    }
    let _ = De::skip;
    Ok(out)
}

//! `favorite`: the user's favorites, materials (with their pictures) and families (with the
//! materials they're made of), kept in a file of their own for every project:
//! `{"version": 1, "materials": {name: {material, images?}}, "families": {name: {family, materials?}}}`.

use super::favjson::{self, FamilyEntry, Favorites, MaterialEntry, PictureFile};
use super::material as mat;
use crate::commands::params::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;

/// Where the favorites are: `BIMCRAFT_FAVORITES`, else `favorites.json` in the configuration
/// folder (`$XDG_CONFIG_HOME/bimcraft`, else `~/.config/bimcraft`).
pub fn default_path() -> String {
    if let Ok(p) = std::env::var("BIMCRAFT_FAVORITES") {
        if !p.is_empty() {
            return p;
        }
    }
    let dir = match std::env::var("XDG_CONFIG_HOME") {
        Ok(x) if !x.is_empty() && std::path::Path::new(&x).is_absolute() => std::path::PathBuf::from(x),
        _ => {
            let home = std::env::var("HOME").unwrap_or_default();
            std::path::Path::new(&home).join(".config")
        }
    };
    dir.join("bimcraft").join("favorites.json").to_string_lossy().to_string()
}

fn io(path: &str, e: &std::io::Error) -> String {
    format!("favorite: {}: {}", path, crate::commands::io_err(e))
}

/// Reads the favorites (none if there's no file yet).
pub fn read(path: &str) -> Result<Favorites, String> {
    let bytes = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Favorites::default()),
        Err(e) => return Err(io(path, &e)),
    };
    let bad = |e: String| format!("favorite: {} isn't a favorites file: {}", path, e);
    if let Err(e) = crate::json::parse_bytes(&bytes) {
        return Err(bad(e.to_string()));
    }
    let favs = favjson::favorites(&bytes).map_err(bad)?;
    // each favorite as it would come into a project
    for (name, e) in &favs.materials {
        if let Err(m) = check_entry(e) {
            return Err(format!("favorite: {}: material `{}`: {}", path, name, m));
        }
    }
    for (name, e) in &favs.families {
        let has_types = e.family.get("types").and_then(|t| t.as_obj()).map(|t| !t.is_empty()).unwrap_or(false);
        if !has_types {
            return Err(format!("favorite: {}: family `{}`: it needs a type: add one to `types`", path, name));
        }
        for (mname, me) in &e.materials {
            if let Err(m) = check_entry(me) {
                return Err(format!("favorite: {}: material `{}`: {}", path, mname, m));
            }
        }
    }
    Ok(favs)
}

/// What a favorite material must be: its texture's tile and its picture.
fn check_entry(e: &MaterialEntry) -> Result<(), String> {
    let Some(t) = e.material.get("texture") else { return Ok(()) };
    let kind = t.get("kind").and_then(|k| k.as_str()).unwrap_or("");
    let size = t.get("size").and_then(|s| s.as_arr()).map(|a| [a[0].as_f64().unwrap_or(0.0), a[1].as_f64().unwrap_or(0.0)]).unwrap_or([0.0, 0.0]);
    let ok = |x: f64| x.is_finite() && (1.0..=1_000_000.0).contains(&x);
    if !ok(size[0]) || !ok(size[1]) {
        return Err(format!(
            "texture: a tile of it is {} by {} mm; each side is 1 to 1000000 mm",
            mat::disp(size[0]),
            mat::disp(size[1])
        ));
    }
    let angle = t.get("angle").and_then(|a| a.as_f64()).unwrap_or(0.0);
    let offset: Vec<f64> = t.get("offset").and_then(|o| o.as_arr()).map(|a| a.iter().filter_map(|x| x.as_f64()).collect()).unwrap_or_default();
    if angle.abs() > 1_000_000.0 || offset.iter().any(|x| (x / 1000.0).abs() > 1_000_000.0) {
        return Err("texture: its angle and its offset need to be numbers".into());
    }
    let image = t.get("image").and_then(|i| i.as_str());
    if kind == "image" {
        match image {
            None => return Err("a texture of a picture needs its file, `path`, or one of the project's, `image`".into()),
            Some(id) => {
                if !e.images.iter().any(|(k, _)| k == id) {
                    let have: Vec<&str> = e.images.iter().map(|(k, _)| k.as_str()).collect();
                    return Err(format!(
                        "texture: it's of picture `{}`, which the project doesn't hold (it has: {})",
                        id,
                        have.join(", ")
                    ));
                }
            }
        }
    } else if image.is_some() {
        return Err("only a texture of kind `image` takes a `path` or an `image`".into());
    }
    Ok(())
}

fn entry_value(e: &MaterialEntry) -> Value {
    let mut m = Map::new();
    m.insert("material", e.material.clone());
    if !e.images.is_empty() {
        let mut im = Map::new();
        for (id, p) in &e.images {
            im.insert(id, jobj! {"name" => p.name.clone(), "png" => p.png.clone()});
        }
        m.insert("images", Value::Obj(im));
    }
    Value::Obj(m)
}

/// Writes the favorites (pretty, as serde_json writes them), making its folder if need be.
pub fn write(path: &str, favs: &Favorites) -> Result<(), String> {
    let mut mats = Map::new();
    for (n, e) in &favs.materials {
        mats.insert(n, entry_value(e));
    }
    let mut fams = Map::new();
    for (n, e) in &favs.families {
        let mut m = Map::new();
        m.insert("family", e.family.clone());
        if !e.materials.is_empty() {
            let mut mm = Map::new();
            for (mn, me) in &e.materials {
                mm.insert(mn, entry_value(me));
            }
            m.insert("materials", Value::Obj(mm));
        }
        fams.insert(n, Value::Obj(m));
    }
    let doc = jobj! {"version" => 1u64, "materials" => Value::Obj(mats), "families" => Value::Obj(fams)};
    if let Some(dir) = std::path::Path::new(path).parent() {
        if !dir.as_os_str().is_empty() {
            std::fs::create_dir_all(dir).map_err(|e| io(path, &e))?;
        }
    }
    std::fs::write(path, doc.to_pretty()).map_err(|e| io(path, &e))
}

fn put<T: Clone>(list: &mut Vec<(String, T)>, name: &str, v: T) {
    match list.binary_search_by(|(k, _)| k.as_str().cmp(name)) {
        Ok(i) => list[i].1 = v,
        Err(i) => list.insert(i, (name.to_string(), v)),
    }
}

// ---------------------------------------------------------------- materials in and out

/// A project's material as a favorite: patterns and its picture by name, with the picture.
pub fn material_entry(pr: &Project, name: &str) -> Option<MaterialEntry> {
    let m = mat::material(pr, name)?;
    let mut v = mat::ordered(m);
    let mut images = Vec::new();
    for key in ["cut_pattern", "surface_pattern"] {
        if let Some(g) = v.get(key).and_then(|x| x.as_str()).map(|s| s.to_string()) {
            if let Some(n) = mat::fill_pattern_name(pr, &g) {
                v.set(key, Value::Str(n));
            }
        }
    }
    if let Some(t) = v.get_mut("texture") {
        if let Some(g) = t.get("image").and_then(|x| x.as_str()).map(|s| s.to_string()) {
            if let Some(id) = mat::picture_id(pr, &g) {
                t.set("image", Value::s(&id));
                if let Some(im) = pr.section("images").and_then(|m| m.get(&id)) {
                    images.push((
                        id.clone(),
                        PictureFile {
                            name: im.get("name").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                            png: im.get("png").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                        },
                    ));
                }
            }
        }
    }
    Some(MaterialEntry { material: v, images })
}

/// Brings a favorite material into the project as `target` (over the one it has, if any).
pub fn load_material(pr: &mut Project, target: &str, e: &MaterialEntry) -> Result<(), String> {
    if mat::material(pr, target).is_none() {
        pr.section_mut("materials").insert_sorted(target, mat::new_material());
        if pr.lib_find("material", target).is_none() {
            pr.lib_add("material", target);
        }
    }
    let mut m = e.material.clone();
    for key in ["cut_pattern", "surface_pattern"] {
        if let Some(n) = m.get(key).and_then(|x| x.as_str()).map(|s| s.to_string()) {
            match mat::fill_pattern_guid(pr, &n) {
                Some(g) => m.set(key, Value::Str(g)),
                None => return Err(format!("material `{}`: there's no fill pattern `{}`", target, n)),
            }
        }
    }
    if let Some(id) = m.get("texture").and_then(|t| t.get("image")).and_then(|x| x.as_str()).map(|s| s.to_string()) {
        if let Some((_, pf)) = e.images.iter().find(|(k, _)| *k == id) {
            if !mat::picture_ids(pr).contains(&id) {
                if mat::picture_ids(pr).len() >= super::picture::MAX_PICTURES {
                    return Err(format!(
                        "favorite: the project holds {} pictures already; take a texture of one away first",
                        super::picture::MAX_PICTURES
                    ));
                }
                pr.section_mut("images").insert_sorted(&id, jobj! {"name" => pf.name.clone(), "png" => pf.png.clone()});
                pr.lib_add("picture", &id);
            }
        }
        let g = mat::picture_guid(pr, &id).unwrap_or_default();
        if let Some(t) = m.get_mut("texture") {
            t.set("image", Value::Str(g));
        }
    }
    pr.section_mut("materials").insert_sorted(target, mat::ordered(&m));
    mat::drop_unused_pictures(pr);
    Ok(())
}

// ---------------------------------------------------------------- families in and out

/// A project's family as a favorite: the materials it names by name, and those materials.
pub fn family_entry(pr: &Project, name: &str) -> Option<FamilyEntry> {
    let f = pr.section("families")?.get(name)?;
    let mut used: Vec<String> = Vec::new();
    let fam = rename_materials(pr, f, &mut used);
    used.sort();
    used.dedup();
    let mut materials = Vec::new();
    for m in used {
        if let Some(e) = material_entry(pr, &m) {
            materials.push((m, e));
        }
    }
    Some(FamilyEntry { family: fam, materials })
}

/// A copy with every material GUID made the material's name.
fn rename_materials(pr: &Project, v: &Value, used: &mut Vec<String>) -> Value {
    match v {
        Value::Str(s) => {
            if crate::model::normalize_guid(s).as_deref() == Some(s.as_str()) {
                if let Some(n) = mat::material_name(pr, s) {
                    used.push(n.clone());
                    return Value::Str(n);
                }
            }
            v.clone()
        }
        Value::Arr(a) => Value::Arr(a.iter().map(|x| rename_materials(pr, x, used)).collect()),
        Value::Obj(m) => {
            let mut out = Map::new();
            for (k, x) in m.iter() {
                out.insert(k, rename_materials(pr, x, used));
            }
            Value::Obj(out)
        }
        _ => v.clone(),
    }
}

// ---------------------------------------------------------------- the command

pub fn cmd(s: &mut Session, p: &Value) -> Result<Value, String> {
    let action = opt_text(p, "favorite", "action")?;
    let kind = opt_text(p, "favorite", "kind")?.unwrap_or_else(|| "material".into());
    if kind != "material" && kind != "family" {
        return Err(format!("favorite: `kind` is material or family, not `{}`", kind));
    }
    let action = action.unwrap_or_else(|| "list".into());
    if !matches!(action.as_str(), "list" | "save" | "load" | "delete") {
        return Err(format!("favorite: `action` is list, save, load or delete, not `{}`", action));
    }
    let path = match opt_text(p, "favorite", "path")? {
        Some(x) => x,
        None => default_path(),
    };
    let whose = if kind == "family" { "the family's" } else { "the material's" };
    let need_name = || -> Result<String, String> {
        match opt_text(p, "favorite", "name")? {
            Some(n) if !n.trim().is_empty() => Ok(n.trim().to_string()),
            _ => Err(format!("favorite: `name` is required: {}", whose)),
        }
    };
    let as_name = || -> Result<Option<String>, String> {
        Ok(opt_text(p, "favorite", "as")?.map(|a| a.trim().to_string()).filter(|a| !a.is_empty()))
    };
    match action.as_str() {
        "list" => {
            let favs = read(&path)?;
            let mats: Vec<Value> = favs
                .materials
                .iter()
                .map(|(n, e)| {
                    let tex = e.material.get("texture").and_then(|t| t.get("kind")).cloned().unwrap_or(Value::Null);
                    jobj! {"color" => e.material.get("color").cloned().unwrap_or(Value::Null), "name" => n.clone(), "texture" => tex}
                })
                .collect();
            let fams: Vec<Value> = favs
                .families
                .iter()
                .map(|(n, e)| {
                    let types: Vec<Value> = e
                        .family
                        .get("types")
                        .and_then(|t| t.as_obj())
                        .map(|t| {
                            let mut k: Vec<String> = t.keys().cloned().collect();
                            k.sort();
                            k.into_iter().map(Value::Str).collect()
                        })
                        .unwrap_or_default();
                    jobj! {"category" => e.family.get("category").cloned().unwrap_or(Value::Null), "name" => n.clone(), "types" => Value::Arr(types)}
                })
                .collect();
            Ok(jobj! {"families" => Value::Arr(fams), "materials" => Value::Arr(mats), "path" => path})
        }
        "save" => {
            let name = need_name()?;
            let target = as_name()?.unwrap_or_else(|| name.clone());
            let pr = &s.project;
            let mut favs = read(&path)?;
            if kind == "material" {
                let e = material_entry(pr, &name).ok_or_else(|| format!("favorite: the library has no `{}`", name))?;
                put(&mut favs.materials, &target, e);
            } else {
                let e = family_entry(pr, &name).ok_or_else(|| format!("favorite: the project has no family `{}`", name))?;
                put(&mut favs.families, &target, e);
            }
            write(&path, &favs)?;
            Ok(jobj! {"kind" => kind, "path" => path, "saved" => target})
        }
        "load" => {
            let name = need_name()?;
            let target = as_name()?.unwrap_or_else(|| name.clone());
            let replace = opt_bool(p, "favorite", "replace")?.unwrap_or(false);
            let favs = read(&path)?;
            let pr = &mut s.project;
            if kind == "material" {
                let e = favs
                    .materials
                    .iter()
                    .find(|(n, _)| *n == name)
                    .map(|(_, e)| e.clone())
                    .ok_or_else(|| format!("favorite: there's no favorite material `{}`", name))?;
                if mat::material(pr, &target).is_some() && !replace {
                    return Err(format!(
                        "favorite: the library has `{}` already: load it `as` another name, or `replace` it",
                        target
                    ));
                }
                load_material(pr, &target, &e)?;
            } else {
                let e = favs
                    .families
                    .iter()
                    .find(|(n, _)| *n == name)
                    .map(|(_, e)| e.clone())
                    .ok_or_else(|| format!("favorite: there's no favorite family `{}`", name))?;
                load_family(pr, &target, &e, replace)?;
            }
            Ok(jobj! {"kind" => kind, "loaded" => target})
        }
        _ => {
            let name = need_name()?;
            let mut favs = read(&path)?;
            let list_len;
            if kind == "material" {
                list_len = favs.materials.len();
                favs.materials.retain(|(n, _)| *n != name);
                if favs.materials.len() == list_len {
                    return Err(format!("favorite: there's no favorite material `{}`", name));
                }
            } else {
                list_len = favs.families.len();
                favs.families.retain(|(n, _)| *n != name);
                if favs.families.len() == list_len {
                    return Err(format!("favorite: there's no favorite family `{}`", name));
                }
            }
            write(&path, &favs)?;
            Ok(jobj! {"deleted" => name, "kind" => kind})
        }
    }
}

/// Brings a favorite family in: the materials it's made of that the project hasn't come by
/// name, then the family with its materials named by GUID.
fn load_family(pr: &mut Project, target: &str, e: &FamilyEntry, replace: bool) -> Result<(), String> {
    let exists = pr.section("families").map(|f| f.contains(target)).unwrap_or(false);
    if exists && !replace {
        return Err(format!(
            "favorite: the project has a family `{}` already: load it `as` another name, or `replace` it",
            target
        ));
    }
    for (mname, me) in &e.materials {
        if mat::material(pr, mname).is_none() {
            load_material(pr, mname, me)?;
        }
    }
    let fam = guid_materials(pr, &e.family);
    if !exists {
        pr.lib_add("family", target);
    }
    pr.section_mut("families").insert_sorted(target, fam);
    Ok(())
}

/// A copy with every material name in `material` and material values made its GUID.
fn guid_materials(pr: &Project, v: &Value) -> Value {
    let mut out = v.clone();
    if let Some(forms) = out.get_mut("forms").and_then(|f| f.as_arr_mut()) {
        for fo in forms.iter_mut() {
            if let Some(n) = fo.get("material").and_then(|m| m.as_str()).map(|s| s.to_string()) {
                if let Some(g) = mat::material_guid(pr, &n) {
                    fo.set("material", Value::Str(g));
                }
            }
        }
    }
    let mut mparams: Vec<String> = Vec::new();
    if let Some(params) = out.get_mut("parameters").and_then(|f| f.as_arr_mut()) {
        for pa in params.iter_mut() {
            if pa.get("kind").and_then(|k| k.as_str()) == Some("material") {
                if let Some(n) = pa.get("name").and_then(|m| m.as_str()) {
                    mparams.push(n.to_string());
                }
                if let Some(n) = pa.get("value").and_then(|m| m.as_str()).map(|s| s.to_string()) {
                    if let Some(g) = mat::material_guid(pr, &n) {
                        pa.set("value", Value::Str(g));
                    }
                }
            }
        }
    }
    if let Some(types) = out.get_mut("types").and_then(|t| t.as_obj_mut()) {
        for (_, t) in types.items.iter_mut() {
            for pn in &mparams {
                if let Some(n) = t.get(pn).and_then(|m| m.as_str()).map(|s| s.to_string()) {
                    if let Some(g) = mat::material_guid(pr, &n) {
                        t.set(pn, Value::Str(g));
                    }
                }
            }
        }
    }
    out
}

