#!/usr/bin/env python3
"""Compare many scenarios between the original and mine. Each scenario: list of run args.
Normalizes GUIDs, uids, tmp names, thread ids in panics."""
import os, re, subprocess, sys, tempfile, shutil, difflib, json
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a950f58ddd6484974/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')

def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    s = re.sub(r"thread 'main' \(\d+\)", "thread 'main' (TID)", s)
    return s

def run(exe, args, files, env_extra=None, setup=None):
    d = tempfile.mkdtemp(prefix='cm')
    for f in files:
        shutil.copy(f, d)
    if setup:
        setup(d)
    env = dict(os.environ)
    env['HOME'] = os.path.join(d, 'home')
    env['XDG_CONFIG_HOME'] = os.path.join(d, 'xdg')
    env.pop('BIMCRAFT_FAVORITES', None)
    if env_extra:
        env.update(env_extra)
    before = set()
    for root, dirs, fs in os.walk(d):
        for f in fs:
            before.add(os.path.relpath(os.path.join(root, f), d))
    p = subprocess.run([exe] + [a.replace('@D', d) for a in args], cwd=d, capture_output=True, timeout=300, env=env)
    out = {'stdout': p.stdout.decode('utf-8', 'replace').replace(d, '@D'), 'stderr': p.stderr.decode('utf-8', 'replace').replace(d, '@D'), 'code': p.returncode}
    fl = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            if rel in before:
                continue
            fl[rel] = open(full, 'rb').read()
    shutil.rmtree(d)
    return out, fl

def compare(args, files=(), quiet=False, env_extra=None, setup=None, label=None):
    o, of = run(ORIG, args, files, env_extra, setup)
    m, mf = run(MINE, args, files, env_extra, setup)
    diffs = []
    for k in ('code', 'stdout', 'stderr'):
        x = norm(str(o[k])); y = norm(str(m[k]))
        if x != y:
            diffs.append(f'--- {k} differs')
            for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=0))[2:12]:
                diffs.append(l[:400])
    for f in sorted(set(of) | set(mf)):
        if f not in of: diffs.append(f'--- file {f} only in mine'); continue
        if f not in mf: diffs.append(f'--- file {f} only in orig'); continue
        x, y = of[f], mf[f]
        try:
            xs = norm(x.decode('utf-8')); ys = norm(y.decode('utf-8'))
        except UnicodeDecodeError:
            if x != y: diffs.append(f'--- binary file {f} differs')
            continue
        if xs != ys:
            diffs.append(f'--- file {f} differs')
            for l in list(difflib.unified_diff(xs.splitlines(), ys.splitlines(), 'orig', 'mine', lineterm='', n=1))[2:20]:
                diffs.append(l[:400])
    ok = not diffs
    name = label or ' '.join(args)[:200]
    if ok:
        if not quiet: print('SAME', name)
    else:
        print('DIFF', name)
        for l in diffs: print('   ', l)
    return ok

def cmds(*cs, save=True):
    a = ['run']
    for c in cs:
        a += ['--cmd', c]
    if save:
        a += ['--save', 'x.bimcraft']
    return a

