def fix_crcs(data):
    """recompute every chunk CRC"""
    out = bytearray(data[:8])
    i = 8
    while i + 8 <= len(data):
        n = struct.unpack('>I', data[i:i + 4])[0]
        t = data[i + 4:i + 8]
        body = data[i + 8:i + 8 + n]
        if i + 12 + n > len(data):
            out += data[i:]
            return bytes(out)
        out += data[i:i + 8 + n] + struct.pack('>I', zlib.crc32(t + body) & 0xffffffff)
        i += 12 + n
    out += data[i:]
    return bytes(out)

