    i = 8
    rs = []
    while i + 8 <= len(data):
        n = struct.unpack('>I', data[i:i + 4])[0]
        t = data[i + 4:i + 8]
        if t == b'IDAT':
            rs.append((i + 8, i + 8 + n))
        i += 12 + n
    return rs

