    kind = random.choice(['flip_idat', 'flip_idat', 'flip_idat_crc', 'flip_any', 'truncate', 'flip_idat_multi', 'garbage_tail', 'drop_bytes'])
    b = bytearray(data)
    if kind.startswith('flip_idat'):
        rs = idat_range(data)
        if not rs:
            return kind, data
        s, e = random.choice(rs)
        if e <= s:
