def lit_code(b):
    if b < 144: return (0b00110000 + b, 8)
    return (0b110010000 + b - 144, 9)
EOB = ('code', 0, 7)
def L(n): return ('code', 0b0000000 + (n - 254), 7) if False else None
def length_code(length):
    # lengths 3..10 -> symbols 257..264 (7-bit codes 0000001..0001000)
    assert 3 <= length <= 10
    sym = 254 + length
    return ('code', sym - 256, 7)
def dist_code(d):
    # distance 1..4 -> codes 0..3 (5 bits), no extra
    assert 1 <= d <= 4
    return ('code', d - 1, 5)
def stream(blocks, adler=True, extra=b''):
    w = BW()
    for final, kind, syms in blocks:
        w.put(final, 1)
        if kind == 'fixed':
            w.put(1, 2)
            for s in syms:
                if s[0] == 'lit': w.put_code(*lit_code(s[1]))
                elif s[0] == 'code': w.put_code(s[1], s[2])
        elif kind == 'stored':
            w.put(0, 2)
            while len(w.bits) % 8: w.bits.append(0)
            n = len(syms)
            w.put(n, 16); w.put((~n) & 0xffff, 16)
            for b in syms: w.put(b, 8)
        elif kind == 'bad':
            w.put(3, 2)
    out = b'\x78\x01' + w.bytes()
    if adler:
        out += b'\x00\x00\x00\x00'
    return out + extra
