        code=(code<<1)|br.bit(); l+=1
        if (l,code) in codes: return codes[(l,code)]
        if l > 16: return None
FIXED_L = [8]*144+[9]*112+[7]*24+[8]*8
def trace(z):
    br = BR(z[2:])
    out = []
    while True:
        bfinal = br.bits(1); bt = br.bits(2)
        print('block final', bfinal, 'type', bt, 'at bit', br.pos)
        if bt == 0:
            br.pos = (br.pos + 7) & ~7
            n = br.bits(16); br.bits(16)
            for i in range(n): out.append(br.bits(8))
            print('  stored', n)
