                if s < 256: out.append(s); print('  lit', s, 'out', len(out), 'inbyte', (br.pos+7)//8 + 2)
                elif s == 256: print('  eob'); break
                else:
                    i = s - 257
                    L = LBASE[i] + br.bits(LEXTRA[i])
                    ds = decode(br, dc)
                    D = DBASE[ds] + br.bits(DEXTRA[ds])
                    print('  match', L, D, 'out before', len(out), 'inbyte', (br.pos+7)//8 + 2, 'TOO FAR' if D > len(out) else '')
                    if D > len(out): return out
                    for k in range(L): out.append(out[-D])
        else:
            print('  bad type'); return out
        if bfinal: break
    return out
def idat(data):
    i = 8; out = b''
    while i + 8 <= len(data):
        n = struct.unpack('>I', data[i:i+4])[0]
        t = data[i+4:i+8]
        if t == b'IDAT': out += data[i+8:i+8+n]
        i += 12 + n
    return out
