/// Reads `n` bytes, or the zune "Not enough bytes" error.
fn take(&mut self, n: usize) -> Result<&'a [u8], Fail> {
    if self.i + n > self.d.len() {
        let found = self.d.len().saturating_sub(self.i);
        return Err(Fail::Error(format!("I/O errors Not enough bytes, expected {} but found {}", n, found)));
    }
    let s = &self.d[self.i..self.i + n];
    self.i += n;
    Ok(s)
}

